// 2e. multicall((address,uint256,bytes)[],bool) — tuple_array + trailing bool
const TUPLE_ARRAY_BOOL_DATA =
  "";

// 2f. multicall((address,bytes)[]) — tuple_array
// Real tx: https://etherscan.io/tx/0x7137114f63ea7be187da13dea150841845180c9f6cdc484ba9de933815e3ae25
const TUPLE_ARRAY_TO_DATA_DATA =
  "";

// 2g. multicall(address[],bytes[]) — parallel_arrays, no values
// Real tx: https://etherscan.io/tx/0x74bc0b91dd531cbab6f6c595ae8badec1f5376708d4eb73625bb9038ba4cfe8b
const PARALLEL_ARRAY_NO_VALUE_DATA =
  "";

// 2h. multicall(address[],bytes[],uint256[],address) — parallel_arrays + trailing address
const PARALLEL_ARRAY_WITH_TO_DATA =
  "";

// 2i. multicall(uint256,bytes[],address[],address[],uint256[],address) — bytes_array at index 1 (data-only)
const MULTI_UINT256_BYTES_ADDRS_DATA =
  "";

// 3. execute(bytes,bytes[]) — Universal Router, no deadline
const UR_NO_DEADLINE_DATA =
  "";

// 4. execute(bytes,bytes[],uint256) — Universal Router with deadline
const UR_WITH_DEADLINE_DATA =
  "";

// 5. Regular function — no multicall
const NORMAL_DATA =
  "0x3244c12c000000000000000000000000000000000000000000000000030d98d59a960000000000000000000000000000b98c948cfa24072e58935bc004a8a7b376ae746a";

const SOURCIFY_SIGNATURES = {
  "0x3244c12c": ["wrapNative(uint256,address)"],
  "0x6ef5eeae": ["erc4626Deposit(address,uint256,uint256,address)"],
  "0x5023b4df": [
    "exactOutputSingle((address,address,uint24,address,uint256,uint256,uint160))",
  ],
  "0x095ea7b3": ["approve(address,uint256)"],
  "0x23b872dd": ["transferFrom(address,address,uint256)"],
  "0xa9059cbb": ["transfer(address,uint256)"],
  "0xdb3e2198": [
    "exactInputSingle((address,address,uint24,address,uint256,uint256,uint256,uint160))",
  ],
  "0x12210e8a": ["refundETH()"],
};

function makeRequest(data) {
  const url = new URL("http://localhost/api/decode");
  url.searchParams.set("data", data);
  return { url: url.toString() };
}

// Handles both the D1 Worker's /api/v1/query?sign= calls (always "no match",
// since sign= never appears in the Sourcify-style regex below) and Sourcify's
// ?function= calls.
function mockSourcify(signatures) {
  return (url) => {
    const selectorMatch = url.match(/function=(0x[0-9a-fA-F]{8})/);
    if (!selectorMatch)
      return Promise.resolve({
        ok: true,
        json: async () => ({ ok: true, result: { function: {} } }),
      });
    const selector = selectorMatch[1];
    const names = signatures[selector] || [];
    return Promise.resolve({
      ok: true,
      json: async () => ({
        ok: true,
        result: {
          function: {
            [selector]: names.map((n) => ({ name: n, filtered: false })),
          },
        },
      }),
    });
  };
}

beforeEach(async () => {
  process.env.CACHE_DIR = CACHE_DIR;
  await resetServerCacheTestDir(CACHE_DIR);
  vi.stubGlobal("fetch", vi.fn());
  process.env.BACKEND_URL = "https://backend.test";
});

afterEach(async () => {
  vi.unstubAllGlobals();
  delete process.env.BACKEND_URL;
  delete process.env.CACHE_DIR;
  await removeServerCacheTestDir(CACHE_DIR);
});

describe("GET /api/decode — multicall augmentation", () => {
  it("multicall((address,bytes,uint256,bool,bytes32)[]) — 3 inner calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(TUPLE_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall((address,bytes,uint256,bool,bytes32)[])");
    expect(d0.inner_calls).toHaveLength(3);
    expect(d0.inner_calls[0].selector).toBeNull();
    expect(d0.inner_calls[1].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[2].selector).toBe("0x6ef5eeae");
    expect(d0.inner_calls[1].decoded.func).toBe("wrapNative(uint256,address)");
    expect(d0.inner_calls[2].decoded.func).toBe(
      "erc4626Deposit(address,uint256,uint256,address)",
    );
  });

  it("multicall(bytes[]) — 2 inner calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(BYTES_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall(bytes[])");
    expect(d0.inner_calls).toHaveLength(2);
    expect(d0.inner_calls[0].selector).toBe("0xdb3e2198");
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");
  });

  it("execute((address,uint256,bytes)[],bytes32) — 3 inner calls with targets/values", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(EXECUTE_TUPLE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute((address,uint256,bytes)[],bytes32)");
    expect(d0.args.commit).toBe(
      "0x00000000000000000000000000000000019eb604f27d700bb64910ebcbef71ee",
    );
    expect(d0.args.calls).toHaveLength(3);
    expect(d0.inner_calls).toHaveLength(3);

    expect(d0.inner_calls[0].target).toBe(
      "0x60FccB9b58d5E806ca5Cb8BFCe721c2274609dE4",
    );
    expect(d0.inner_calls[0].value).toBe(0);
    expect(d0.inner_calls[0].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[0].decoded.func).toBe("wrapNative(uint256,address)");

    expect(d0.inner_calls[1].target).toBe(
      "0x904861a24F30EC96ea7CFC3bE9EA4B476d237e98",
    );
    expect(d0.inner_calls[1].value).toBe("11974268881699143");
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");

    expect(d0.inner_calls[2].target).toBe(
      "0x8E60b7b64b63cD56b18ebcECADcb79B04919286e",
    );
    expect(d0.inner_calls[2].selector).toBeNull();
    expect(d0.inner_calls[2].data).toBe("0x");
  });

  it("multicall(uint256,bytes[]) — deadline + 1 inner call (real tx 0x503cda58…)", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(MC_UINT256_BYTES_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall(uint256,bytes[])");
    expect(d0.args.deadline).toBe(1786702051);
    expect(d0.args.data).toHaveLength(1);
    expect(d0.inner_calls).toHaveLength(1);
    expect(d0.inner_calls[0].selector).toBe("0x5023b4df");
    expect(d0.inner_calls[0].decoded.func).toBe(
      "exactOutputSingle((address,address,uint24,address,uint256,uint256,uint160))",
    );
  });

  it("execute(address[],uint256[],bytes[],bytes32) — 9 inner calls (real tx 0x0d867785…)", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(PARALLEL_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute(address[],uint256[],bytes[],bytes32)");
    expect(d0.args.targets).toHaveLength(9);
    expect(d0.args.values).toHaveLength(9);
    expect(d0.args.calldatas).toHaveLength(9);
    expect(d0.args.descriptionHash).toBe(
      "0xeeef007e0a1b43779e1bd7556bea7036ac37de82ead814ab56b076bf54049fc6",
    );
    expect(d0.inner_calls).toHaveLength(9);

    expect(d0.inner_calls[0].target).toBe(
      "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    );
    expect(d0.inner_calls[0].selector).toBe("0x095ea7b3");
    expect(d0.inner_calls[0].decoded.func).toBe("approve(address,uint256)");
    expect(d0.inner_calls[0].value).toBe(0);

    // 0x45977d03 / 0x57e6aa36 have no Sourcify match — no `decoded` attached
    expect(d0.inner_calls[1].selector).toBe("0x45977d03");
    expect(d0.inner_calls[1].decoded).toBeUndefined();
    expect(d0.inner_calls[3].selector).toBe("0x57e6aa36");
    expect(d0.inner_calls[3].decoded).toBeUndefined();

    expect(d0.inner_calls[2].selector).toBe("0xa9059cbb");
    expect(d0.inner_calls[2].decoded.func).toBe("transfer(address,uint256)");

    expect(d0.inner_calls[8].target).toBe(
      "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    );
    expect(d0.inner_calls[8].selector).toBe("0xa9059cbb");
    expect(d0.inner_calls[8].decoded.func).toBe("transfer(address,uint256)");
  });

  it("multicall((address,uint256,bytes)[],bool) — 2 inner calls with targets/values", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(TUPLE_ARRAY_BOOL_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall((address,uint256,bytes)[],bool)");
    expect(d0.args.strict).toBe(true);
    expect(d0.inner_calls).toHaveLength(2);

    expect(d0.inner_calls[0].target).toBe(
      "0x60FccB9b58d5E806ca5Cb8BFCe721c2274609dE4",
    );
    expect(d0.inner_calls[0].value).toBe(0);
    expect(d0.inner_calls[0].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[0].decoded.func).toBe("wrapNative(uint256,address)");

    expect(d0.inner_calls[1].target).toBe(
      "0x904861a24F30EC96ea7CFC3bE9EA4B476d237e98",
    );
    expect(d0.inner_calls[1].value).toBe(1000000000000000);
    expect(d0.inner_calls[1].selector).toBeNull();
    expect(d0.inner_calls[1].data).toBe("0x");
  });

  it("multicall((address,bytes)[]) — 2 inner calls with targets (real tx 0x7137114f…)", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(TUPLE_ARRAY_TO_DATA_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall((address,bytes)[])");
    expect(d0.inner_calls).toHaveLength(2);

    expect(d0.inner_calls[0].target).toBe(
      "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    );
    expect(d0.inner_calls[0].selector).toBe("0x23b872dd");
    expect(d0.inner_calls[0].decoded.func).toBe(
      "transferFrom(address,address,uint256)",
    );

    expect(d0.inner_calls[1].target).toBe(
      "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    );
    expect(d0.inner_calls[1].selector).toBe("0x23b872dd");
    expect(d0.inner_calls[1].decoded.func).toBe(
      "transferFrom(address,address,uint256)",
    );
  });

  it("multicall(address[],bytes[]) — 1 inner call, no values (real tx 0x74bc0b91…)", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(PARALLEL_ARRAY_NO_VALUE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall(address[],bytes[])");
    expect(d0.args.targets).toHaveLength(1);
    expect(d0.args.calldatas).toHaveLength(1);
    expect(d0.inner_calls).toHaveLength(1);

    expect(d0.inner_calls[0].target).toBe(
      "0xdAC17F958D2ee523a2206206994597C13D831ec7",
    );
    expect(d0.inner_calls[0].value).toBeUndefined();
    expect(d0.inner_calls[0].selector).toBe("0x095ea7b3");
    expect(d0.inner_calls[0].decoded.func).toBe("approve(address,uint256)");
  });

  it("multicall(address[],bytes[],uint256[],address) — 2 inner calls with values", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(PARALLEL_ARRAY_WITH_TO_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall(address[],bytes[],uint256[],address)");
    expect(d0.args.to).toBe("0x8E60b7b64b63cD56b18ebcECADcb79B04919286e");
    expect(d0.inner_calls).toHaveLength(2);

    expect(d0.inner_calls[0].target).toBe(
      "0x60FccB9b58d5E806ca5Cb8BFCe721c2274609dE4",
    );
    expect(d0.inner_calls[0].value).toBe(0);
    expect(d0.inner_calls[0].selector).toBe("0x3244c12c");

    expect(d0.inner_calls[1].target).toBe(
      "0x904861a24F30EC96ea7CFC3bE9EA4B476d237e98",
    );
    expect(d0.inner_calls[1].value).toBe(5000000000000000);
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");
  });

  it("multicall(uint256,bytes[],address[],address[],uint256[],address) — 2 inner calls, data-only", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(MULTI_UINT256_BYTES_ADDRS_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe(
      "multicall(uint256,bytes[],address[],address[],uint256[],address)",
    );
    expect(d0.args.deadline).toBe(1786702051);
    expect(d0.args.data).toHaveLength(2);
    expect(d0.inner_calls).toHaveLength(2);

    expect(d0.inner_calls[0].target).toBeUndefined();
    expect(d0.inner_calls[0].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[0].decoded.func).toBe("wrapNative(uint256,address)");

    expect(d0.inner_calls[1].target).toBeUndefined();
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");
  });

  it("execute(bytes,bytes[]) — Universal Router, 5 commands", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(UR_NO_DEADLINE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute(bytes,bytes[])");
    expect(d0.inner_calls).toHaveLength(5);
    expect(d0.inner_calls[0].name).toBe("V3_SWAP_EXACT_IN");
    expect(d0.inner_calls[1].name).toBe("PERMIT2_TRANSFER_FROM_BATCH");
    expect(d0.inner_calls[2].name).toBe("V2_SWAP_EXACT_OUT");
    expect(d0.inner_calls[3].name).toBe("UNKNOWN_0x0f");
    expect(d0.inner_calls[4].name).toBe("PERMIT2_TRANSFER_FROM");
  });

  it("execute(bytes,bytes[],uint256) — Universal Router with deadline, 3 commands", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(UR_WITH_DEADLINE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute(bytes,bytes[],uint256)");
    expect(d0.inner_calls).toHaveLength(3);
    expect(d0.inner_calls[0].name).toBe("WRAP_ETH");
    expect(d0.inner_calls[1].name).toBe("V3_SWAP_EXACT_IN");
    expect(d0.inner_calls[2].name).toBe("SWEEP");
  });

  it("regular function — no inner_calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(NORMAL_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("wrapNative(uint256,address)");
    expect(d0.source).toBe("sourcify");
    expect(d0.inner_calls).toBeUndefined();
  });
});
